/* eslint-disable no-undef -- dev-only Node script (run with `node`), not app code */
/**
 * Dev-only generator: extracts clean, web-usable monochrome SVGs from the native
 * macOS app's SF Symbols provider-logo symbolsets (agent-deck/Assets.xcassets/
 * <name>.symbolset) and writes them + the provider-id→logo mapping to
 * apps/web/src/assets/providerLogos.ts. The GENERATED file is committed so the
 * build never depends on the native repo; re-run this only when the native logos
 * change. Reuses the native app's own assets (no invented icons).
 *
 * Usage (from apps/web): node scripts/generate-provider-logos.mjs <path-to-Assets.xcassets>
 */
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";

// provider-id → symbolset name, ported verbatim from native ProviderLogo.swift.
const PROVIDER_TO_SYMBOL = {
  anthropic: "claude",
  "azure-openai-responses": "openai",
  openai: "openai",
  "openai-codex": "openai",
  "github-copilot": "copilot",
  "kimi-coding": "kimi",
  moonshotai: "kimi",
  "moonshotai-cn": "kimi",
  minimax: "minimax",
  "minimax-cn": "minimax",
  mistral: "mistralai",
  opencode: "opencode",
  "opencode-go": "opencode",
  openrouter: "openrouter",
  "vercel-ai-gateway": "vercel",
  xai: "xai",
  zai: "zai",
  "zai-coding-cn": "zai",
  cerebras: "cerebras",
  deepseek: "deepseek",
  google: "google",
  "google-vertex": "google",
  neuralwatt: "neuralwatt",
  nvidia: "nvidia",
  xiaomi: "xiaomi",
  "xiaomi-token-plan-ams": "xiaomi",
  "xiaomi-token-plan-cn": "xiaomi",
  "xiaomi-token-plan-sgp": "xiaomi",
  perplexity: "perplexity",
  qwen: "qwen",
  gemini: "gemini",
  github: "github",
  pi: "pi",
};

function extractSymbol(svgText) {
  const m = svgText.match(/<g id="Regular-S"[^>]*>([\s\S]*?)<\/g>\s*(?=<g id="|<\/g>\s*<\/g>)/);
  if (!m) throw new Error("no Regular-S group");
  const inner = m[1].trim();
  const paths = [...inner.matchAll(/<path\b[^>]*\bd="[^"]*"[^>]*>/g)].map((p) => p[0]);
  if (paths.length === 0) throw new Error("no paths");
  let minX = Infinity,
    minY = Infinity,
    maxX = -Infinity,
    maxY = -Infinity;
  for (const d of inner.match(/\bd="([^"]*)"/g) ?? []) {
    const nums = (d.match(/-?\d+(?:\.\d+)?/g) ?? []).map(Number);
    for (let i = 0; i + 1 < nums.length; i += 2) {
      const x = nums[i],
        y = nums[i + 1];
      if (x < minX) minX = x;
      if (x > maxX) maxX = x;
      if (y < minY) minY = y;
      if (y > maxY) maxY = y;
    }
  }
  const pad = (maxX - minX) * 0.04;
  const vb = [minX - pad, minY - pad, maxX - minX + 2 * pad, maxY - minY + 2 * pad]
    .map((n) => Number(n.toFixed(2)))
    .join(" ");
  const body = paths.join("").replace(/\s(fill|stroke)="[^"]*"/g, "");
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${vb}" fill="currentColor">${body}</svg>`;
}

const assetsDir = process.argv[2];
if (!assetsDir) throw new Error("pass the path to Assets.xcassets");
const symbols = new Set(Object.values(PROVIDER_TO_SYMBOL));
const logos = {};
for (const symbol of [...symbols].sort()) {
  const dir = path.join(assetsDir, `${symbol}.symbolset`);
  const svg = readdirSync(dir).find((f) => f.endsWith(".svg"));
  logos[symbol] = extractSymbol(readFileSync(path.join(dir, svg), "utf8"));
}
const out =
  `// GENERATED by scripts/generate-provider-logos.mjs from the native app's SF\n` +
  `// Symbols provider-logo symbolsets. Do not edit by hand — re-run the generator.\n` +
  `// Monochrome SVGs (fill=currentColor) so they theme with the surrounding text.\n\n` +
  `/** Raw SVG markup per logo key (the native symbolset name). */\n` +
  `export const PROVIDER_LOGOS: Record<string, string> = ${JSON.stringify(logos, null, 2)};\n\n` +
  `/** pi provider id → logo key (native ProviderLogo mapping). */\n` +
  `export const PROVIDER_LOGO_KEY: Record<string, string> = ${JSON.stringify(PROVIDER_TO_SYMBOL, null, 2)};\n`;
writeFileSync(path.join("src", "assets", "providerLogos.ts"), out);

// Brand/misc marks used in the chrome (not provider logos): the pi mark on
// assistant messages, the paperplane, and the git symbols on the Git screen.
const BRAND_SYMBOLS = ["pi", "paperplane", "branch", "git-commit"];
const brand = {};
for (const symbol of BRAND_SYMBOLS) {
  const dir = path.join(assetsDir, `${symbol}.symbolset`);
  const svg = readdirSync(dir).find((f) => f.endsWith(".svg"));
  // camelCase the key so it's a clean TS identifier map (git-commit → gitCommit).
  const key = symbol.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
  brand[key] = extractSymbol(readFileSync(path.join(dir, svg), "utf8"));
}
const brandOut =
  `// GENERATED by scripts/generate-provider-logos.mjs from the native app's SF\n` +
  `// Symbols brand/misc symbolsets. Do not edit by hand — re-run the generator.\n` +
  `// Monochrome SVGs (fill=currentColor) so they theme with the surrounding text.\n\n` +
  `/** Raw SVG markup per brand-icon key. */\n` +
  `export const BRAND_ICONS = ${JSON.stringify(brand, null, 2)} as const;\n\n` +
  `export type BrandIconName = keyof typeof BRAND_ICONS;\n`;
writeFileSync(path.join("src", "assets", "brandIcons.ts"), brandOut);

console.log(`wrote ${Object.keys(logos).length} logos + ${Object.keys(brand).length} brand icons`);
